  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useMemo } from 'react';
  4→import { HeroReel } from '@/components/HeroReel';
  5→import { LadderGrid } from '@/components/LadderGrid';
  6→import { usePerception } from '@/lib/perception/context';
  7→import { projects, projectsBySlug } from '@/lib/projects';
  8→import { ProjectAdapter } from '@/lib/perception/adapter';
  9→import { useIsMobile } from '@/lib/hooks/useIsMobile';
 10→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
 11→
 12→// Hoisted static styles — avoids creating new objects on every render
 13→const scrollIndicatorTextStyle = {
 14→  color: '#8a8a8a',
 15→  fontFamily: 'var(--font-display)',
 16→  fontSize: '11px',
 17→  fontWeight: 600,
 18→  letterSpacing: '0.04em',
 19→  textTransform: 'uppercase' as const,
 20→  marginTop: '8px'
 21→};
 22→
 23→const gradientOverlayStyle = {
 24→  height: '250px',
 25→  background: 'linear-gradient(to bottom, #141414 0%, transparent 100%)',
 26→  zIndex: 95,
 27→  opacity: 0
 28→};
 29→
 30→const heroSectionStyle = {
 31→  maxWidth: 'var(--max-content-width)',
 32→  paddingLeft: 'var(--side-padding)',
 33→  paddingRight: 'var(--side-padding)',
 34→  paddingTop: 'clamp(102px, 10.2vw + 34px, 170px)',
 35→  paddingBottom: 'clamp(102px, 10.2vw + 34px, 170px)',
 36→};
 37→
 38→const heroTextWrapperStyle = { maxWidth: '900px' };
 39→
 40→const gridSectionStyle = {
 41→  maxWidth: 'var(--max-content-width)',
 42→  paddingLeft: 'var(--side-padding)',
 43→  paddingRight: 'var(--side-padding)',
 44→  paddingBottom: 'var(--space-lg)',
 45→};
 46→
 47→export default function HomePage() {
 48→  // Get perception state from context (sensor runs in PerceptionLayer)
 49→  const { archetype, confidence } = usePerception();
 50→
 51→  const { isMobile } = useIsMobile();
 52→  const prefersReducedMotion = usePrefersReducedMotion();
 53→
 54→  const [introVisible, setIntroVisible] = useState(false);
 55→
 56→  // Refs for scroll-driven DOM updates (no re-renders on scroll)
 57→  const scrollIndicatorRef = useRef<HTMLDivElement>(null);
 58→  const introTextRef = useRef<HTMLElement>(null);
 59→  const gradientOverlayRef = useRef<HTMLDivElement>(null);
 60→
 61→  // Hero height based on device - matches HeroReel component
 62→  const heroHeight = isMobile ? '50vh' : '70vh';
 63→  const heroHeightMultiplier = isMobile ? 0.5 : 0.7;
 64→
 65→  // Trigger intro animation on mount
 66→  useEffect(() => {
 67→    const timer = setTimeout(() => setIntroVisible(true), 100);
 68→    return () => clearTimeout(timer);
 69→  }, []);
 70→
 71→  // Listen for chatbot open/close via custom event (replaces MutationObserver)
 72→  useEffect(() => {
 73→    const scrollIndicator = scrollIndicatorRef.current;
 74→    if (!scrollIndicator) return;
 75→
 76→    const observer = new MutationObserver(() => {
 77→      const isOpen = document.body.hasAttribute('data-chatbot-open');
 78→      if (scrollIndicator) {
 79→        scrollIndicator.style.opacity = isOpen ? '0' : scrollIndicator.dataset.scrollOpacity || '1';
 80→        scrollIndicator.style.pointerEvents = isOpen ? 'none' : 'auto';
 81→      }
 82→    });
 83→
 84→    observer.observe(document.body, { attributes: true, attributeFilter: ['data-chatbot-open'] });
 85→    return () => observer.disconnect();
 86→  }, []);
 87→
 88→  // Scroll-driven opacity updates via direct DOM manipulation (no React re-renders)
 89→  useEffect(() => {
 90→    const handleScroll = () => {
 91→      const scrollY = window.scrollY;
 92→
 93→      // Fade out scroll indicator between 0-300px scroll
 94→      const scrollIndicatorOp = Math.max(0, 1 - (scrollY / 300));
 95→      if (scrollIndicatorRef.current) {
 96→        scrollIndicatorRef.current.dataset.scrollOpacity = String(scrollIndicatorOp);
 97→        // Only update DOM if chatbot isn't overriding
 98→        if (!document.body.hasAttribute('data-chatbot-open')) {
 99→          scrollIndicatorRef.current.style.opacity = String(scrollIndicatorOp);
100→          scrollIndicatorRef.current.style.pointerEvents = scrollIndicatorOp === 0 ? 'none' : 'auto';
101→        }
102→      }
103→
104→      // Fade out intro text right before it overlaps navigation
105→      const fadeStart = 600;
106→      const fadeEnd = 800;
107→      let introOp = 1;
108→      if (scrollY > fadeStart) {
109→        introOp = Math.max(0, 1 - ((scrollY - fadeStart) / (fadeEnd - fadeStart)));
110→      }
111→      if (introTextRef.current) {
112→        introTextRef.current.style.opacity = String(introOp);
113→      }
114→
115→      // Fade gradient overlay for content scrolling under navigation
116→      const currentHeroHeight = window.innerHeight * heroHeightMultiplier;
117→      const contentTopPosition = currentHeroHeight - scrollY;
118→      const navHeight = 200;
119→      let mainTopOp = 1;
120→      if (contentTopPosition < navHeight) {
121→        const fadeDistance = 150;
122→        const distanceIntoNav = navHeight - contentTopPosition;
123→        mainTopOp = Math.max(0, 1 - (distanceIntoNav / fadeDistance));
124→      }
125→      if (gradientOverlayRef.current) {
126→        gradientOverlayRef.current.style.opacity = mainTopOp < 1 ? String((1 - mainTopOp) * 0.95) : '0';
127→      }
128→    };
129→
130→    window.addEventListener('scroll', handleScroll, { passive: true });
131→    return () => window.removeEventListener('scroll', handleScroll);
132→  }, [heroHeightMultiplier]);
133→
134→  // Find General Reel for hero (O(1) Map lookup)
135→  const heroProject = projectsBySlug.get('general-reel');
136→
137→  // Hero statement - authentic, consistent regardless of mode
138→  const heroStatement = "Sixteen years. Feature films, commercials, real-time engines—each frame a problem of light solved in pixels. This is the work.";
139→
140→  // Adapt project order based on visitor archetype
141→  // Only adapts when confidence > 0.5 to avoid premature/unstable reordering
142→  const adaptedProjects = useMemo(() => {
143→    const gridProjects = projects.filter(p => p.slug !== 'general-reel');
144→
145→    // Confidence threshold: don't adapt on weak signal
146→    if (confidence < 0.5 || !archetype) {
147→      return gridProjects;
148→    }
149→
150→    return ProjectAdapter.adaptProjectOrder(gridProjects, archetype);
151→  }, [archetype, confidence]);
152→
153→  return (
154→    <>
155→      {/* Hero Reel - Fixed position, crossfades on scroll, below navigation */}
156→      {heroProject && (
157→        <HeroReel
158→          videoId={heroProject.videoId}
159→          videoHash={heroProject.videoHash}
160→          startTime={heroProject.startTime}
161→          thumbnail={heroProject.thumbnail}
162→        />
163→      )}
164→
165→      {/* Scroll indicator - positioned right below hero reel, hidden when chatbot is open */}
166→      <div
167→        ref={scrollIndicatorRef}
168→        className="fixed left-0 right-0 flex flex-col items-center"
169→        style={{
170→          top: `calc(${heroHeight} - 60px)`,
171→          zIndex: 90,
172→          opacity: 1,
173→          transition: 'opacity 0.3s ease-out'
174→        }}
175→      >
176→        <svg
177→          className="scroll-chevron"
178→          width="24"
179→          height="24"
180→          viewBox="0 0 24 24"
181→          fill="none"
182→          stroke="#8a8a8a"
183→          strokeWidth="2"
184→          strokeLinecap="round"
185→          strokeLinejoin="round"
186→        >
187→          <polyline points="6 9 12 15 18 9" />
188→        </svg>
189→        <p style={scrollIndicatorTextStyle}>
190→          Scroll
191→        </p>
192→      </div>
193→
194→      {/* Gradient fade overlay for content scrolling under navigation */}
195→      <div
196→        ref={gradientOverlayRef}
197→        className="fixed top-0 left-0 right-0 pointer-events-none"
198→        style={gradientOverlayStyle}
199→      />
200→
201→      {/* Main content - starts below viewport, scrolls up */}
202→      <main className="min-h-screen relative" style={{ marginTop: heroHeight, zIndex: 50, backgroundColor: '#141414' }}>
203→        {/* Hero Statement - Isolated quote with generous whitespace (Pentagram style) */}
204→        <section
205→          ref={introTextRef}
206→          className="mx-auto"
207→          style={heroSectionStyle}
208→        >
209→          <div style={heroTextWrapperStyle}>
210→            {/* Hero Statement - Editorial serif quote style, Pentagram-tight heading */}
211→            <h1
212→              style={{
213→                color: '#a0a0a0',
214→                fontFamily: 'var(--font-lora)',
215→                fontWeight: 400,
216→                fontStyle: 'italic',
217→                fontSize: 'clamp(22px, 3.5vw, 38px)',
218→                lineHeight: 1.2,
219→                letterSpacing: '0.005em',
220→                opacity: introVisible ? 1 : 0,
221→                transform: introVisible ? 'translateY(0)' : `translateY(${isMobile ? 20 : 30}px)`,
222→                transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1), transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1)'
223→              }}
224→            >
225→              {heroStatement}
226→            </h1>
227→          </div>
228→        </section>
229→
230→        {/* Ladder Grid - Golden ratio spacing (excludes hero reel to avoid duplication) */}
231→        <section
232→          className="mx-auto"
233→          style={gridSectionStyle}
234→        >
235→          <LadderGrid projects={adaptedProjects} />
236→        </section>
237→      </main>
238→    </>
239→  );
240→}
