 1→import type { MetadataRoute } from 'next';
 2→import { projects } from '@/lib/projects';
 3→import { getProcessPostsByCategory } from '@/lib/process-posts';
 4→
 5→export default function sitemap(): MetadataRoute.Sitemap {
 6→  const baseUrl = 'https://josephibrahim.com';
 7→
 8→  // Static pages
 9→  const staticPages: MetadataRoute.Sitemap = [
10→    {
11→      url: baseUrl,
12→      lastModified: new Date(),
13→      changeFrequency: 'weekly',
14→      priority: 1,
15→    },
16→    {
17→      url: `${baseUrl}/info`,
18→      lastModified: new Date(),
19→      changeFrequency: 'monthly',
20→      priority: 0.8,
21→    },
22→    {
23→      url: `${baseUrl}/photo`,
24→      lastModified: new Date(),
25→      changeFrequency: 'monthly',
26→      priority: 0.7,
27→    },
28→    {
29→      url: `${baseUrl}/process`,
30→      lastModified: new Date(),
31→      changeFrequency: 'weekly',
32→      priority: 0.8,
33→    },
34→  ];
35→
36→  // Project pages
37→  const projectPages: MetadataRoute.Sitemap = projects.map((project) => ({
38→    url: `${baseUrl}/projects/${project.slug}`,
39→    lastModified: new Date(),
40→    changeFrequency: 'monthly' as const,
41→    priority: 0.9,
42→  }));
43→
44→  // Process posts (all categories)
45→  const categories = ['case-studies', 'tools', 'research', 'experiments'] as const;
46→  const allProcessPosts = categories.flatMap(cat => getProcessPostsByCategory(cat));
47→  const processPages: MetadataRoute.Sitemap = allProcessPosts.map((post) => ({
48→    url: `${baseUrl}/process/${post.slug}`,
49→    lastModified: new Date(),
50→    changeFrequency: 'monthly' as const,
51→    priority: 0.7,
52→  }));
53→
54→  return [...staticPages, ...projectPages, ...processPages];
55→}
