 1→import { notFound } from 'next/navigation';
 2→import { ProjectContentWrapper } from '@/components/ProjectContentWrapper';
 3→import { ProjectDetailContent } from '@/components/ProjectDetailContent';
 4→import { ProjectHeroReel } from '@/components/ProjectHeroReel';
 5→import { ScrollReset } from '@/components/ScrollReset';
 6→import { projects, type Project } from '@/lib/projects';
 7→import { genAiProjects } from '@/lib/gen-ai-projects';
 8→import type { Metadata } from 'next';
 9→
10→interface ProjectPageProps {
11→  params: Promise<{ slug: string }>;
12→}
13→
14→// Combine all projects for lookup
15→const allProjects = [...projects, ...genAiProjects];
16→
17→function findProject(slug: string): Project | undefined {
18→  return allProjects.find(p => p.slug === slug);
19→}
20→
21→export async function generateStaticParams() {
22→  // Generate routes for both regular and Gen AI projects
23→  return allProjects.map((project) => ({
24→    slug: project.slug,
25→  }));
26→}
27→
28→export async function generateMetadata({ params }: ProjectPageProps): Promise<Metadata> {
29→  const { slug } = await params;
30→  const project = findProject(slug);
31→
32→  if (!project) {
33→    return {
34→      title: 'Project Not Found',
35→    };
36→  }
37→
38→  return {
39→    title: project.title,
40→    description: project.description,
41→  };
42→}
43→
44→export default async function ProjectPage({ params }: ProjectPageProps) {
45→  const { slug } = await params;
46→  const project = findProject(slug);
47→
48→  if (!project) {
49→    notFound();
50→  }
51→
52→  return (
53→    <>
54→      {/* Ensure scroll starts at top - user lands on autoplay hero */}
55→      <ScrollReset />
56→
57→      {/* Hero Reel - Fixed position autoplay, extends to top edge */}
58→      <ProjectHeroReel
59→        videoId={project.videoId}
60→        videoHash={project.videoHash}
61→        startTime={project.startTime}
62→        thumbnail={project.thumbnail}
63→      />
64→
65→      {/* Main content - positioned below hero with responsive marginTop */}
66→      <ProjectContentWrapper>
67→        <main
68→          className="mx-auto pb-32"
69→          style={{
70→            maxWidth: 'var(--max-content-width)',
71→            paddingTop: 'clamp(60px, 5vw + 30px, 100px)',
72→            paddingLeft: 'var(--side-padding)',
73→            paddingRight: 'var(--side-padding)'
74→          }}
75→        >
76→          <ProjectDetailContent project={project} />
77→        </main>
78→      </ProjectContentWrapper>
79→    </>
80→  );
81→}
